\title{Analogy as an Adjoint Operation: Galois Connections, Closure, Fidelity, and the Tropical Residual}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
We develop a mathematical theory of analogy-making between ordered structures. An analogy from a source poset $A$ to a target poset $B$ is a pair of order-preserving maps $(F,G)$ --- a \emph{forward} map $F:A\to B$ and a \emph{backward} map $G:B\to A$ --- satisfying the adjunction law $F(a)\le b \iff a\le G(b)$; that is, a monotone Galois connection. From this single law we derive the entire structural theory: (i) the round-trip map $G\circ F$ is a closure operator on $A$ (inflationary, monotone, idempotent), while $F\circ G$ is dually an interior operator on $B$; (ii) the backward map is \emph{uniquely} determined by the forward map, given by $G(b)=\sup\{a:F(a)\le b\}$; (iii) the \emph{fidelity} of an analogy --- the number of source points recovered exactly by a round trip --- equals the cardinality of the image of $G\circ F$, and is maximized precisely by the \emph{perfect} analogies, those with $G\circ F=\id_A$. We then instantiate the theory in the min-plus (tropical) semiring, where min-plus matrix multiplication $v\mapsto A\otimes v$ is paired with its canonical adjoint, the max-plus \emph{residual} $A^\sharp$. The adjunction specializes to the classical reconstruction inequalities $w\le A\otimes(A^\sharp w)$ and $A^\sharp(A\otimes v)\le v$, recovering the standard theory of solving min-plus linear systems and shortest-path reconstruction. We give algorithms, applications, and a program of conjectures relating fidelity to a rank-type invariant, to Lipschitz-optimal reconstruction, and to order isomorphisms of stable cores.
\end{abstract}

\maketitle

\section{Introduction}

Analogy --- the recognition that two ostensibly different structures share a common relational skeleton --- is a central mode of reasoning, usually studied informally. Our goal is to treat analogy as a genuine mathematical \emph{operation} between ordered structures, with laws, a canonical best form, and quantitative invariants.

The key move is to insist that an analogy is a \emph{matched pair}: a forward translation together with a backward translation, bound by a compatibility law that makes each map the best possible partner of the other --- the \emph{adjunction} condition of a monotone Galois connection. This explains several intuitive properties of good analogies: that translating a concept out and back can only stabilize it (closure), that the backward interpretation is forced by the forward map (uniqueness), and that some analogies are strictly more faithful than others (fidelity). In the tropical semiring --- the arithmetic of optimization and shortest paths --- the abstract best analogy is a concrete, computable object: the residual matrix.

\section{Preliminaries}

A \emph{partially ordered set} (poset) is a set $P$ with a relation $\le$ that is reflexive, antisymmetric, and transitive. A map $f:P\to Q$ is \emph{monotone} if $x\le y$ implies $f(x)\le f(y)$. We interpret a poset as a conceptual world: $x\le y$ means ``$x$ is subsumed by / more specific than $y$.'' Central for us is $\Rbar^n=(\mathbb{R}\cup\{+\infty\})^n$ with the coordinatewise order.

\section{Analogies as adjoint pairs}

\begin{definition}[Analogy]\label{def:analogy}
Let $(A,\le)$ and $(B,\le)$ be posets. An \emph{analogy} from $A$ to $B$ is a pair $(F,G)$ of maps $F:A\to B$ and $G:B\to A$ such that
\begin{equation}\label{eq:adj}
F(a)\le b \quad\Longleftrightarrow\quad a\le G(b)\qquad\text{for all } a\in A,\ b\in B.
\end{equation}
We call $F$ the \emph{forward} map and $G$ the \emph{backward} map; $(F,G)$ is a monotone Galois connection with $F$ left adjoint and $G$ right adjoint.
\end{definition}

\begin{proposition}\label{prop:mono}
If $(F,G)$ is an analogy, then $F$ and $G$ are monotone.
\end{proposition}
\begin{proof}
If $a\le a'$, then from $F(a')\le F(a')$ and \eqref{eq:adj} we get $a'\le G(F(a'))$, so $a\le G(F(a'))$, and \eqref{eq:adj} gives $F(a)\le F(a')$. The claim for $G$ is dual.
\end{proof}

\begin{proposition}[Unit and counit]\label{prop:unitcounit}
For all $a\in A$, $b\in B$: $\ a\le G(F(a))$ and $F(G(b))\le b$.
\end{proposition}
\begin{proof}
Apply \eqref{eq:adj} to $F(a)\le F(a)$ and to $G(b)\le G(b)$ respectively.
\end{proof}

\begin{proposition}[Triangle identities]\label{prop:triangle}
$F\circ G\circ F=F$ and $G\circ F\circ G=G$.
\end{proposition}
\begin{proof}
Apply monotone $F$ to $a\le GFa$ to get $Fa\le FGFa$; the counit at $Fa$ gives $FGFa\le Fa$; antisymmetry yields equality. The other identity is dual.
\end{proof}

\begin{definition}[Closure / interior operator]
A \emph{closure operator} on $P$ is $C:P\to P$ that is inflationary ($x\le C(x)$), monotone, and idempotent ($C\circ C=C$). Dually an \emph{interior operator} is deflationary, monotone, and idempotent.
\end{definition}

\begin{theorem}\label{thm:closure}
For an analogy $(F,G)$, the map $C:=G\circ F$ is a closure operator on $A$, and $K:=F\circ G$ is an interior operator on $B$.
\end{theorem}
\begin{proof}
Inflationary: Proposition~\ref{prop:unitcounit}. Monotone: Proposition~\ref{prop:mono}. Idempotent: apply $G$ to $FGF=F$ (Proposition~\ref{prop:triangle}) to get $GFGF=GF$. The statement for $K$ is dual.
\end{proof}

\begin{theorem}[Uniqueness of the backward map]\label{thm:unique}
The backward map is uniquely determined by the forward map: if $G,G'$ both complete $F$ into an analogy then $G=G'$, and whenever the suprema exist,
\begin{equation}\label{eq:Gformula}
G(b)=\sup\{\,a\in A: F(a)\le b\,\}.
\end{equation}
\end{theorem}
\begin{proof}
Fix $b$. By \eqref{eq:adj}, $a\le G(b)\iff F(a)\le b$, so $G(b)$ is an upper bound of $S_b:=\{a:F(a)\le b\}$; and $G(b)\in S_b$ since $F(G(b))\le b$ (counit). Hence $G(b)=\max S_b=\sup S_b$, proving \eqref{eq:Gformula}. The right-hand side depends only on $F$, giving uniqueness.
\end{proof}

\begin{remark}
When $A$ is a complete lattice, $F$ admits a completing backward map iff $F$ preserves arbitrary suprema, in which case $G$ is given by \eqref{eq:Gformula}. In finite settings this is unconditional.
\end{remark}

\section{Fidelity}

\begin{definition}[Stable concept]
A concept $a\in A$ is \emph{stable} under $(F,G)$ if $G(F(a))=a$, i.e.\ $a$ is a fixed point of $C=G\circ F$.
\end{definition}

By Theorem~\ref{thm:closure}, the stable set equals the image $C(A)$.

\begin{definition}[Fidelity]
For an analogy over a finite source $A$, the \emph{fidelity} is
\[
\Phi(F,G):=\#\{\,a\in A: G(F(a))=a\,\}=\#\,C(A).
\]
\end{definition}

\begin{proposition}\label{prop:fid}
$0<\Phi(F,G)\le \#A$, and the stable set equals $C(A)$.
\end{proposition}
\begin{proof}
Each fixed point lies in $C(A)$; conversely $c=C(a)$ satisfies $C(c)=C(C(a))=C(a)=c$ by idempotence, so $C(A)$ consists of fixed points. It is nonempty and bounded by $\#A$.
\end{proof}

\begin{definition}[Perfect analogy]
$(F,G)$ is \emph{perfect} if $G\circ F=\id_A$.
\end{definition}

\begin{theorem}[Fidelity maximization]\label{thm:maxfid}
Over a fixed finite source $A$, an analogy attains $\Phi=\#A$ if and only if it is perfect.
\end{theorem}
\begin{proof}
If perfect, every $a$ is stable so $\Phi=\#A$, the maximum by Proposition~\ref{prop:fid}. Conversely $\Phi=\#A$ forces $GFa=a$ for all $a$, i.e.\ $G\circ F=\id_A$.
\end{proof}

This is the precise sense in which the best analogies maximize structural similarity: $G\circ F$ is as close to the identity as possible, equal to it exactly for perfect analogies.

\section{The tropical instantiation}

The \emph{min-plus} (tropical) semiring is $\Rbar=\mathbb{R}\cup\{+\infty\}$ with $x\oplus y=\min(x,y)$ and $x\otimes y=x+y$; additive identity $+\infty$, multiplicative identity $0$. On vectors, order is coordinatewise and
\[
(A\otimes v)_i=\min_j\big(A_{ij}+v_j\big),\qquad A\in\Rbar^{m\times n},\ v\in\Rbar^n,
\]
the Bellman relaxation step of shortest-path computation.

The min-plus product $v\mapsto A\otimes v$ preserves coordinatewise infima, hence is a right adjoint; its uniquely determined left-adjoint partner uses the dual (max-plus) operations.

\begin{definition}[Residual]
For $A\in\Rbar^{m\times n}$, the \emph{residual} $A^\sharp:\Rbar^m\to\Rbar^n$ is
\[
(A^\sharp w)_j:=\max_i\big(w_i-A_{ij}\big),
\]
with $w_i-(+\infty)=-\infty$ so that missing edges impose no constraint.
\end{definition}

\begin{theorem}[Tropical analogy]\label{thm:trop}
With the forward (reconstruction) map $F(w)=A^\sharp w$ and the backward (encoding) map $G(v)=A\otimes v$ under the coordinatewise order, $(F,G)$ is an analogy:
\[
A^\sharp w\le v\quad\Longleftrightarrow\quad w\le A\otimes v.
\]
\end{theorem}
\begin{proof}
$w\le A\otimes v$ iff $w_i\le A_{ij}+v_j$ for all $i,j$ iff $w_i-A_{ij}\le v_j$ for all $i,j$ iff $\max_i(w_i-A_{ij})\le v_j$ for all $j$, i.e.\ $A^\sharp w\le v$. This is the residuation adjunction \eqref{eq:adj}, with $A^\sharp w$ the least super-solution of $A\otimes(\cdot)\ge w$.
\end{proof}

By Theorem~\ref{thm:unique}, $A^\sharp$ is the unique adjoint partner: the canonical best analogy of a min-plus map, computed with the opposite (max/subtraction) operations.

\begin{corollary}[Reconstruction inequalities]
$w\le A\otimes(A^\sharp w)$ and $A^\sharp(A\otimes v)\le v$.
\end{corollary}
\begin{proof}
Specialize Proposition~\ref{prop:unitcounit}.
\end{proof}

These trap any round trip; the residual is the tightest reconstruction (the unit and counit of Proposition~\ref{prop:unitcounit}). The system $A\otimes x=b$ is solvable iff $A\otimes(A^\sharp b)=b$, in which case $A^\sharp b$ is the greatest solution --- the classical shortest-path / potential recovery.

\section{Algorithms}
\begin{itemize}
\item \textbf{Verify an adjunction:} check \eqref{eq:adj} over all pairs; $O(\#A\cdot\#B)$ comparisons.
\item \textbf{Induced backward map:} $G(b)=\sup\{a:F(a)\le b\}$; $O(\#A\cdot\#B)$ joins.
\item \textbf{Fidelity:} count fixed points of $C=G\circ F$; $O(\#A)$ round trips.
\item \textbf{Tropical residual:} form $A^\sharp$, evaluate the reconstruction sandwich, test solvability; $O(mn)$ per residuation.
\end{itemize}

\section{Applications}
Modeling conceptual hierarchies as posets, an analogy is a validated forward/backward pair; fidelity measures lossless transfer and the closure operator identifies the trustworthy stable core. In min-plus, the forward map is a lossy encoder and the residual its canonical decoder, with the reconstruction inequalities certifying no fabricated detail. Residuation solves min-plus systems modeling shortest paths, scheduling, and allocation, unifying primal cost computation and dual potential recovery as two halves of one analogy. Galois connections between objects and attributes underlie formal concept analysis, where our invariants compare conceptual scalings.

\section{Future directions}

\begin{conjecture}[Fidelity as a rank-type invariant]
Fidelity equals $\#\,C(A)$ and is monotone under composition: the fidelity of a composite analogy never exceeds the smaller of the component fidelities.
\end{conjecture}

\begin{conjecture}[Lipschitz-optimal reconstruction]
Among all backward maps paired with a fixed forward map, the adjoint minimizes the worst-case reconstruction defect in the sup-metric; tropically this optimal defect is controlled by the spread of matrix entries along each column.
\end{conjecture}

\begin{conjecture}[Perfect cores]
Every analogy restricts to an order isomorphism between the image of its source-side closure operator and the image of its target-side interior operator.
\end{conjecture}

\section{Conclusion}
Defining analogy as an adjoint pair bound by a single balancing law forces a rich theory: round trips are closures, backward maps are unique, and fidelity is a countable invariant maximized exactly by perfect analogies. In the tropical semiring the abstract best analogy is the concrete residual, and the round-trip inequalities become the classical reconstruction sandwich. Analogy admits a precise algebra.

\end{document}

