function VERIFY-ADJUNCTION(A, B, <=_A, <=_B, F, G):
    for each a in A:
        for each b in B:
            if (F(a) <=_B b) != (a <=_A G(b)):
                return FALSE
    return TRUE

function INDUCED-BACKWARD(A, B, <=_A, <=_B, F):
    function G(b):
        S <- { a in A : F(a) <=_B b }
        if S is empty: return bottom(A)
        return JOIN(S)          // least upper bound in A
    return G

function SOLVE-MINPLUS(A, b):
    for j in 1..n:
        x[j] <- max over i of (b[i] - A[i][j])   // residual A^# b
    for i in 1..m:
        r[i] <- min over j of (A[i][j] + x[j])   // A (x) x
    if r == b: return x            // greatest solution
    else:      return NONE         // system unsolvable
